CREATE TABLE IF NOT EXISTS `coa_dungeon_rescale_item` (
    `entry` INT UNSIGNED PRIMARY KEY,
    `pve_power` SMALLINT UNSIGNED NOT NULL,
    `pvp_power` SMALLINT UNSIGNED NOT NULL
) ENGINE=InnoDB;

CREATE TEMPORARY TABLE `_coa_hellfire_dungeon_gear` (
    `original` INT UNSIGNED NOT NULL,
    `target` INT UNSIGNED PRIMARY KEY,
    `ItemLevel` INT NOT NULL,
    `RequiredLevel` INT NOT NULL,
    `armor` INT NOT NULL,
    `block` INT NOT NULL,
    `socketBonus` INT NOT NULL,
    `stat_value1` INT NOT NULL,
    `stat_value2` INT NOT NULL,
    `stat_value3` INT NOT NULL,
    `stat_value4` INT NOT NULL,
    `stat_value5` INT NOT NULL,
    `stat_value6` INT NOT NULL,
    `stat_value7` INT NOT NULL,
    `stat_value8` INT NOT NULL,
    `stat_value9` INT NOT NULL,
    `stat_value10` INT NOT NULL,
    `holy_res` INT NOT NULL,
    `fire_res` INT NOT NULL,
    `nature_res` INT NOT NULL,
    `frost_res` INT NOT NULL,
    `shadow_res` INT NOT NULL,
    `arcane_res` INT NOT NULL,
    `dmg_min1` DECIMAL(12,3) NOT NULL,
    `dmg_min2` DECIMAL(12,3) NOT NULL,
    `dmg_max1` DECIMAL(12,3) NOT NULL,
    `dmg_max2` DECIMAL(12,3) NOT NULL,
