    `spellid_2` INT NOT NULL,
    `spellid_3` INT NOT NULL,
    `spellid_4` INT NOT NULL,
    `spellid_5` INT NOT NULL
) ENGINE=InnoDB;

DELETE FROM `_coa_hellfire_dungeon_gear`;

DELETE FROM `item_template` WHERE `entry` IN (SELECT `target` FROM `_coa_hellfire_dungeon_gear` WHERE `target` <> `original`);
