 `s`.`spellcategorycooldown_5`, `s`.`bonding`, CONCAT(CASE WHEN b.ItemLevel=65 THEN '@Normal Dungeon@' WHEN b.ItemLevel=68 THEN '@Heroic Dungeon@' ELSE '@Mythic Dungeon@' END, ' ', s.description), `s`.`PageText`, `s`.`LanguageID`, `s`.`PageMaterial`, `s`.`startquest`, `s`.`lockid`, `s`.`Material`, `s`.`sheath`, `s`.`RandomProperty`, `s`.`RandomSuffix`, `b`.`block`, `s`.`itemset`, `s`.`MaxDurability`, `s`.`area`, `s`.`Map`, `s`.`BagFamily`, `s`.`TotemCategory`, `s`.`socketColor_1`, `s`.`socketContent_1`, `s`.`socketColor_2`, `s`.`socketContent_2`, `s`.`socketColor_3`, `s`.`socketContent_3`, `b`.`socketBonus`, `s`.`GemProperties`, `s`.`RequiredDisenchantSkill`, `s`.`ArmorDamageModifier`, `s`.`duration`, `s`.`ItemLimitCategory`, `s`.`HolidayId`, `s`.`ScriptName`, `s`.`DisenchantID`, `s`.`FoodType`, `s`.`minMoneyLoot`, `s`.`maxMoneyLoot`, `s`.`flagsCustom`, `s`.`VerifiedBuild`
