UPDATE `item_template` `i` JOIN `_coa_hellfire_dungeon_gear` `b` ON `i`.`entry` = `b`.`target` AND `b`.`target` = `b`.`original`
SET `i`.`ItemLevel` = `b`.`ItemLevel`, `i`.`RequiredLevel` = `b`.`RequiredLevel`, `i`.`armor` = `b`.`armor`, `i`.`block` = `b`.`block`, `i`.`socketBonus` = `b`.`socketBonus`, `i`.`stat_value1` = `b`.`stat_value1`, `i`.`stat_value2` = `b`.`stat_value2`, `i`.`stat_value3` = `b`.`stat_value3`, `i`.`stat_value4` = `b`.`stat_value4`, `i`.`stat_value5` = `b`.`stat_value5`, `i`.`stat_value6` = `b`.`stat_value6`, `i`.`stat_value7` = `b`.`stat_value7`, `i`.`stat_value8` = `b`.`stat_value8`, `i`.`stat_value9` = `b`.`stat_value9`, `i`.`stat_value10` = `b`.`stat_value10`, `i`.`holy_res` = `b`.`holy_res`, `i`.`fire_res` = `b`.`fire_res`, `i`.`nature_res` = `b`.`nature_res`, `i`.`frost_res` = `b`.`frost_res`, `i`.`shadow_res` = `b`.`shadow_res`, `i`.`arcane_res` = `b`.`arcane_res`, `i`.`dmg_min1` = `b`.`dmg_min1`, `i`.`dmg_min2` = `b`.`dmg_min2`, `i`.`dmg_max1` = `b`.`dmg_max1`, `i`.`dmg_max2` = `b`.`dmg_max2`, `i`.`spellid_1` = `b`.`spellid_1`, `i`.`spellid_2` = `b`.`spellid_2`, `i`.`spellid_3` = `b`.`spellid_3`, `i`.`spellid_4` = `b`.`spellid_4`, `i`.`spellid_5` = `b`.`spellid_5`;

DELETE FROM `coa_dungeon_rescale_item` WHERE `entry` IN (SELECT `target` FROM `_coa_hellfire_dungeon_gear`);

DELETE FROM `item_dbc` WHERE `ID` IN (SELECT `target` FROM `_coa_hellfire_dungeon_gear`);
SELECT i.`entry`,i.`class`,i.`subclass`,i.`SoundOverrideSubclass`,i.`Material`,i.`displayid`,i.`InventoryType`,i.`sheath`
FROM `item_template` i JOIN `_coa_hellfire_dungeon_gear` b ON b.`target`=i.`entry`;
DROP TEMPORARY TABLE `_coa_hellfire_dungeon_gear`;
